146	random\_batch (v1) & 8 & 0.249 & 0.446 & 0.320 \\
147	per\_type & 66 & 0.194 & 0.586 & 0.292 \\
148	\midrule
149	sdgd\_zero (v2) & 4 & 0.324 & 0.191 & 0.241 \\
150	random\_batch (v2) & 8 & 0.331 & 0.276 & 0.301 \\
151	\bottomrule
152	\end{tabular}}
